def clean_text(v):
    v = re.sub(r'(?<=[A-Za-zÀ-ÿ])(?=\d)', ' ', v)
    v = re.sub(r'(?<=\d)(?=[A-Za-zÀ-ÿ])', ' ', v)
    return v
for rows in [sources, milestones]:
    for row in rows:
        for key in ['description','significance','supports','retrieval_status','title','source_date']:
            if key in row: row[key] = clean_text(row[key])

for name, rows in [('sources',sources),('milestones',milestones)]:
    (OUT/f'{name}.json').write_text(json.dumps(rows,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
    with (OUT/f'{name}.csv').open('w',encoding='utf-8',newline='') as fh:
        w=csv.DictWriter(fh,fieldnames=list(rows[0])); w.writeheader(); w.writerows(rows)
print(f'Wrote {len(sources)} sources and {len(milestones)} milestones')
